import buble from 'rollup-plugin-buble'

const pack = require('./package.json')
const YEAR = new Date().getFullYear()

export default {
  entry: 'src/index.js',
  dest: 'dist/dotin.js',
  plugins: [
    buble()
  ],
  banner   () {
    return `/*!
    * ${pack.name} v${pack.version}
    * (c) ${YEAR} ${pack.author}
    * Release under the ${pack.license} License.
*/`
  }
}
